components.css:
.ds-btn-outline{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:36px;padding:0 16px;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-md,8px);background:var(--background,#FAF8FF);color:var(--foreground,#131B2E);font-family:inherit;font-size:14px;font-weight:500;line-height:1;white-space:nowrap;cursor:pointer;transition:background-color .2s ease,color .2s ease,box-shadow .2s ease;}
.ds-btn-outline svg{flex:none;}
.ds-btn-outline:hover{background:var(--accent,#F2F3FF);color:var(--accent-foreground,#131B2E);}
.ds-btn-outline:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}

.ds-card{position:relative;display:flex;flex-direction:column;width:100%;max-width:300px;overflow:hidden;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-xl,12px);background:var(--card,#FFFFFF);color:var(--foreground,#131B2E);font-family:inherit;box-shadow:var(--shadow-card,0 1px 2px 0 rgb(15 23 42 / .05));transition:box-shadow .2s ease;}
.ds-card:hover{box-shadow:var(--shadow-card-hover,0 4px 6px -1px rgb(15 23 42 / .08));}
.ds-card-media{display:grid;place-items:center;aspect-ratio:4/3;background:var(--muted,#F2F3FF);color:var(--muted-foreground,#50434D);}
.ds-card-badge{position:absolute;top:12px;left:12px;padding:4px 10px;border-radius:var(--radius-full,9999px);background:var(--card,#FFFFFF);color:var(--foreground,#131B2E);font-size:11px;font-weight:600;line-height:1;letter-spacing:.02em;}
.ds-card-fav{position:absolute;top:8px;right:8px;display:grid;place-items:center;width:32px;height:32px;padding:0;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-full,9999px);background:var(--card,#FFFFFF);color:var(--muted-foreground,#50434D);cursor:pointer;transition:color .2s ease;}
.ds-card-fav:hover{color:var(--primary,#6C1D6E);}
.ds-card-fav:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}
.ds-card-body{padding:16px;}
.ds-card-price{margin:0 0 6px;color:var(--primary,#6C1D6E);font-size:20px;font-weight:700;line-height:1.3;letter-spacing:-.02em;}
.ds-card-title{display:-webkit-box;margin:0 0 8px;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;font-size:18px;font-weight:600;line-height:1.35;}
.ds-card-meta{display:flex;align-items:center;gap:6px;margin:0;color:var(--muted-foreground,#50434D);font-size:12px;line-height:1.2;}
.ds-card-meta svg{flex:none;}

.ds-header{display:flex;align-items:center;gap:16px;height:72px;padding:0 24px;border-bottom:1px solid var(--border,#E2E8F0);background:color-mix(in srgb,var(--card,#FFFFFF) 95%,transparent);font-family:inherit;}
.ds-brand{display:inline-flex;align-items:center;gap:10px;flex:none;}
.ds-brand-tile{display:grid;place-items:center;width:40px;height:40px;border-radius:var(--radius-xl,12px);background:var(--primary,#6C1D6E);color:var(--primary-foreground,#FFFFFF);box-shadow:var(--shadow-card,0 1px 2px 0 rgb(15 23 42 / .05));}
.ds-brand-name{font-size:18px;font-weight:700;letter-spacing:-.02em;color:var(--primary,#6C1D6E);white-space:nowrap;}
.ds-header-search{display:flex;align-items:center;gap:8px;flex:1;min-width:0;max-width:480px;height:44px;margin:0 auto;padding:0 6px 0 12px;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-full,9999px);background:var(--background,#FAF8FF);color:var(--muted-foreground,#50434D);transition:border-color .2s ease,box-shadow .2s ease;}
.ds-header-search:focus-within{border-color:var(--ring,#6C1D6E);box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 20%,transparent);}
.ds-header-search input{flex:1;min-width:0;border:0;background:transparent;color:var(--foreground,#131B2E);font-family:inherit;font-size:14px;outline:none;}
.ds-header-search input::placeholder{color:var(--muted-foreground,#50434D);}
.ds-header-search button{display:grid;place-items:center;width:32px;height:32px;padding:0;border:0;border-radius:var(--radius-full,9999px);background:var(--primary,#6C1D6E);color:var(--primary-foreground,#FFFFFF);cursor:pointer;}
.ds-header-cta{display:inline-flex;align-items:center;gap:6px;flex:none;height:44px;padding:0 16px;border:0;border-radius:var(--radius-full,9999px);background:var(--primary,#6C1D6E);color:var(--primary-foreground,#FFFFFF);font-family:inherit;font-size:14px;font-weight:500;cursor:pointer;transition:background-color .2s ease;}
.ds-header-cta:hover{background:var(--primary-hover,#541456);}
.ds-header-cta:focus-visible,.ds-header-search button:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}
@media (max-width:760px){.ds-header-search{display:none;}}

.ds-hero-search{display:flex;align-items:center;gap:4px;width:100%;max-width:820px;padding:8px;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-2xl,16px);background:var(--card,#FFFFFF);font-family:inherit;box-shadow:var(--shadow-card,0 1px 2px 0 rgb(15 23 42 / .05));}
.ds-hero-seg{display:flex;align-items:center;gap:8px;flex:1;min-width:0;height:48px;padding:0 12px;border-radius:var(--radius-xl,12px);color:var(--muted-foreground,#50434D);}
.ds-hero-seg svg{flex:none;}
.ds-hero-seg input,.ds-hero-seg select{flex:1;min-width:0;border:0;background:transparent;color:var(--foreground,#131B2E);font-family:inherit;font-size:14px;outline:none;}
.ds-hero-seg input::placeholder{color:var(--muted-foreground,#50434D);}
.ds-hero-seg select{appearance:none;font-weight:500;cursor:pointer;}
.ds-hero-seg:focus-within{box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 20%,transparent);}
.ds-hero-divider{flex:none;width:1px;height:32px;background:var(--border,#E2E8F0);}
.ds-hero-submit{display:inline-flex;align-items:center;justify-content:center;flex:none;height:48px;padding:0 20px;border:0;border-radius:var(--radius-full,9999px);background:var(--primary,#6C1D6E);color:var(--primary-foreground,#FFFFFF);font-family:inherit;font-size:15px;font-weight:600;cursor:pointer;transition:background-color .2s ease;}
.ds-hero-submit:hover{background:var(--primary-hover,#541456);}
.ds-hero-submit:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}
@media (max-width:640px){.ds-hero-search{flex-direction:column;align-items:stretch;}.ds-hero-divider{width:100%;height:1px;}.ds-hero-submit{height:44px;border-radius:var(--radius-xl,12px);}}

.ds-empty{display:flex;flex-direction:column;align-items:center;gap:10px;max-width:560px;padding:56px 24px;border:1px dashed var(--border,#E2E8F0);border-radius:var(--radius-2xl,16px);background:var(--card,#FFFFFF);text-align:center;font-family:inherit;}
.ds-empty-tile{display:grid;place-items:center;width:56px;height:56px;border-radius:var(--radius-2xl,16px);background:var(--primary-muted,#F8EEF9);color:var(--primary,#6C1D6E);}
.ds-empty h2{margin:6px 0 0;font-size:18px;font-weight:600;line-height:1.4;color:var(--foreground,#131B2E);}
.ds-empty p{max-width:42ch;margin:0;font-size:14px;line-height:1.6;color:var(--muted-foreground,#50434D);}
.ds-empty-actions{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin-top:10px;}
.ds-empty-primary,.ds-empty-outline{display:inline-flex;align-items:center;justify-content:center;height:36px;padding:0 16px;border-radius:var(--radius-md,8px);font-family:inherit;font-size:14px;font-weight:500;cursor:pointer;transition:background-color .2s ease;}
.ds-empty-primary{border:0;background:var(--primary,#6C1D6E);color:var(--primary-foreground,#FFFFFF);}
.ds-empty-primary:hover{background:var(--primary-hover,#541456);}
.ds-empty-outline{border:1px solid var(--border,#E2E8F0);background:var(--background,#FAF8FF);color:var(--foreground,#131B2E);}
.ds-empty-outline:hover{background:var(--accent,#F2F3FF);}
.ds-empty-primary:focus-visible,.ds-empty-outline:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}

.ds-dialog-scrim{display:grid;place-items:center;width:100%;padding:16px;background:color-mix(in srgb,#000 50%,transparent);font-family:inherit;}
.ds-dialog{position:relative;display:flex;flex-direction:column;gap:16px;width:100%;max-width:420px;padding:24px;border:1px solid var(--border,#E2E8F0);border-radius:var(--radius-lg,10px);background:var(--background,#FAF8FF);color:var(--foreground,#131B2E);box-shadow:0 10px 15px -3px rgb(0 0 0 / .1),0 4px 6px -4px rgb(0 0 0 / .1);}
.ds-dialog-close{position:absolute;top:16px;right:16px;display:grid;place-items:center;width:24px;height:24px;padding:0;border:0;border-radius:var(--radius-sm,4px);background:transparent;color:var(--muted-foreground,#50434D);cursor:pointer;opacity:.7;transition:opacity .2s ease;}
.ds-dialog-close:hover{opacity:1;}
.ds-dialog-close:focus-visible{outline:none;box-shadow:0 0 0 2px var(--ring,#6C1D6E);}
.ds-dialog-title{margin:0;font-size:18px;font-weight:600;line-height:1.35;letter-spacing:-.01em;}
.ds-dialog-desc{margin:0;font-size:14px;line-height:1.55;color:var(--muted-foreground,#50434D);}
.ds-dialog-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:8px;}
.ds-dialog-outline,.ds-dialog-danger{display:inline-flex;align-items:center;justify-content:center;height:36px;padding:0 16px;border-radius:var(--radius-md,8px);font-family:inherit;font-size:14px;font-weight:500;cursor:pointer;transition:background-color .2s ease;}
.ds-dialog-outline{border:1px solid var(--border,#E2E8F0);background:var(--background,#FAF8FF);color:var(--foreground,#131B2E);}
.ds-dialog-outline:hover{background:var(--accent,#F2F3FF);}
.ds-dialog-danger{border:0;background:var(--destructive,#BA1A1A);color:#fff;}
.ds-dialog-danger:hover{background:color-mix(in srgb,var(--destructive,#BA1A1A) 90%,#000);}
.ds-dialog-outline:focus-visible,.ds-dialog-danger:focus-visible{outline:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--ring,#6C1D6E) 50%,transparent);}
